function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // suffering waves
  ctx.beginPath();
  ctx.moveTo(0, H/2 + 100);
  for (let i = 0; i < W; i++) {
    ctx.lineTo(i, H/2 + 100 + 20 * Math.sin(t + i/50));
  }
  ctx.stroke();

  // purpose arrow
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 150);
  ctx.lineTo(W/2, H/2 + 200 + 20 * Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200 + 20 * Math.cos(t));
  ctx.lineTo(W/2 - 10, H/2 + 210 + 20 * Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200 + 20 * Math.cos(t));
  ctx.lineTo(W/2 + 10, H/2 + 210 + 20 * Math.cos(t));
  ctx.stroke();

  ctx.restore();
}
